<span class="line"><span style="color:#D6DEEB">        tasks </span><span style="color:#C792EA">=</span><span style="color:#D9F5DD"> [</span><span style="color:#B2CCD6">generate</span><span style="color:#D6DEEB">(</span><span style="color:#82AAFF">session</span><span style="color:#D9F5DD">,</span><span style="color:#82AAFF"> p</span><span style="color:#D6DEEB">) </span><span style="color:#C792EA;font-style:italic">for</span><span style="color:#D6DEEB"> p </span><span style="color:#C792EA;font-style:italic">in</span><span style="color:#D6DEEB"> prompts</span><span style="color:#D9F5DD">]</span></span>
